    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg or (r,c) in seen: continue
            color=grid[r][c]; cells=set(); q=deque([(r,c)]); seen.add((r,c))
            while q:
                y,x=q.popleft(); cells.add((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    z=(y+dy,x+dx)
                    if 0<=z[0]<h and 0<=z[1]<w and z not in seen and grid[z[0]][z[1]]==color:
                        seen.add(z); q.append(z)
            out.append((color,cells))
    return out

def _lshape(cells):
    if len(cells)<3:return None
    r0,r1=min(y for y,x in cells),max(y for y,x in cells); c0,c1=min(x for y,x in cells),max(x for y,x in cells)
    for (r,c),a,b in [((r0,c0),(0,1),(1,0)),((r0,c1),(0,-1),(1,0)),((r1,c0),(0,1),(-1,0)),((r1,c1),(0,-1),(-1,0))]:
        aa={(r+k*a[0],c+k*a[1]) for k in range(c1-c0+1 if a[1] else r1-r0+1)}
        bb={(r+k*b[0],c+k*b[1]) for k in range(c1-c0+1 if b[1] else r1-r0+1)}
        if cells==aa|bb:return (r,c),a,b
    return None

def transform(grid):
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps=_components(grid,bg)
    markers=[(co,cells,_lshape(cells)) for co,cells in comps if _lshape(cells)]
    if not markers:return [row[:] for row in grid]
    color,marker,((r,c),a,b)=max(markers,key=lambda z:len(z[1]))
    horizontal=a if a[1] else b
    side=-horizontal[1]
    candidates=[]
    for co,cells in comps:
        if cells==marker:continue
        xs=[x for y,x in cells]; ys=[y for y,x in cells]
        if (sum(xs)/len(xs)-c)*side<=0:continue
        # Choose the closest two-cell horizontal object across the L's vertical arm.
        if len(cells)==2 and len(set(ys))==1:
